from typing import Dict, List, Set
import heapq

def topo_sort(deps: Dict[str, List[str]]) -> List[str]:
    # Collect all unique nodes (both keys and items in dependency lists)
    all_nodes: Set[str] = set()
    for node, requirements in deps.items():
        all_nodes.add(node)
        for req in requirements:
            all_nodes.add(req)

    # Build adjacency list (graph) and in-degree count
    # Since deps maps item -> items it depends on,
    # an edge exists from req -> node.
    # To have dependencies come first, we want edges from dependency to dependent.
    graph: Dict[str, List[str]] = {node: [] for node in all_nodes}
    in_degree: Dict[str, int] = {node: 0 for node in all_nodes}

    for node, requirements in deps.items():
        for req in requirements:
            graph[req].append(node)
            in_degree[node] += 1

    # Initialize min-heap with nodes having 0 in-degree for deterministic alphabetical order
    heap: List[str] = [node for node, degree in in_degree.items() if degree == 0]
    heapq.heapify(heap)

    result: List[str] = []

    while heap:
        current = heapq.heappop(heap)
        result.append(current)

        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    # If result doesn't contain all nodes, there is a cycle
    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected in dependencies")

    return result
